<!doctype html><html lang="fr"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Objectifs — Budget Josh</title><style>:root{--ink:#123b35;--paper:#f4f2ec;--card:#fffefa;--line:#dbe2da;--green:#197451;--muted:#647873}*{box-sizing:border-box}body{margin:0;background:var(--paper);font:15px Arial;color:var(--ink)}header,main{max-width:1250px;margin:auto;padding:0 18px}header{padding-top:30px}.back{color:var(--green);font-weight:bold;text-decoration:none}.ey{font-size:10px;letter-spacing:.15em;color:var(--muted);font-weight:bold;margin:18px 0 5px}h1{margin:0;font-size:32px}.intro{color:var(--muted);margin:7px 0 18px}.btn{border:0;border-radius:10px;padding:11px 14px;background:var(--ink);color:#fff;font:inherit;font-weight:bold;cursor:pointer}.metrics{display:grid;grid-template-columns:repeat(3,1fr);gap:9px;margin:14px 0}.metric{background:var(--card);border:1px solid var(--line);padding:13px;border-radius:12px}.metric b{font-size:21px;display:block}.metric small{color:var(--muted)}.board{overflow:auto;border:1px solid var(--line);border-radius:16px;background:var(--card)}table{border-collapse:separate;border-spacing:0;min-width:max-content;width:100%}th,td{border-right:1px solid var(--line);border-bottom:1px solid var(--line);padding:10px;vertical-align:top;min-width:145px}th{background:#eef3ee;text-align:left}.track{position:sticky;left:0;background:#f8faf6!important;z-index:2;min-width:210px!important;display:flex;align-items:center;justify-content:space-between;gap:6px;font-weight:bold}.edit-track{border:0;background:#e7eee8;color:var(--ink);border-radius:50%;width:24px;height:24px;flex:0 0 auto;font-size:12px;cursor:pointer}.current{background:#dff1e5!important}.task{display:flex;gap:5px;align-items:start;margin:5px 0;font-size:12px}.task button{border:0;border-radius:99px;background:#dfe2dc;color:#31413b;min-width:25px;height:25px;cursor:pointer}.task.done button{background:var(--green);color:#fff}.task.done span{text-decoration:line-through;color:var(--muted)}.add{border:0;background:transparent;color:var(--green);font-weight:bold;font-size:12px;padding:3px 0;cursor:pointer}dialog{border:0;border-radius:18px;width:min(470px,100%);padding:20px}form{display:grid;gap:11px;position:relative}input,textarea{padding:11px;border:1px solid var(--line);border-radius:8px;font:inherit}textarea{min-height:110px}.close{position:absolute;right:0;top:-5px;border:0;border-radius:50%;font-size:20px;width:32px;height:32px}@media(max-width:600px){header,main{padding:0 12px}.metrics{grid-template-columns:1fr}h1{font-size:27px}}</style></head><body><header><a class="back" href="/">← Retour aux budgets</a><p class="ey">OBJECTIFS</p><h1>Vos repères mois par mois.</h1><p class="intro">Une ligne est un objectif global ; chaque case contient les actions prévues pour le mois.</p></header><main><button class="btn" id="addTrack">+ Nouvel objectif global</button><section class="metrics" id="metrics"></section><p class="ey">PLANIFICATION</p><div class="board"><table><thead id="months"></thead><tbody id="rows"></tbody></table></div></main><dialog id="trackDialog"><form id="trackForm"><button class="close" type="button">×</button><h2>Objectif global</h2><input id="trackTitle" required placeholder="Ex. Se former dans le web"><button class="btn">Ajouter la ligne</button></form></dialog><dialog id="taskDialog"><form id="taskForm"><button class="close" type="button">×</button><h2 id="taskTitle"></h2><textarea id="taskText" required placeholder="Action précise à réaliser pendant ce mois"></textarea><button class="btn">Ajouter l’action</button></form></dialog><script src="uuid-polyfill.js"></script><script src="objectives.js?v=<?= @filemtime(__DIR__.'/objectives.js')?:time() ?>"></script></body></html>
